function FunctionCurve({points}:{points:readonly {x:number;y:number}[]}){if(points.length<2)return null;const xs=points.map(p=>p.x),ys=points.map(p=>p.y),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),xr=xmax-xmin||1,yr=ymax-ymin||1;const path=points.map((p,i)=>`${i?"L":"M"} ${((p.x-xmin)/xr*100).toFixed(3)} ${(100-(p.y-ymin)/yr*100).toFixed(3)}`).join(" ");const xAxis=ymin<=0&&ymax>=0?100-(0-ymin)/yr*100:null,yAxis=xmin<=0&&xmax>=0?(0-xmin)/xr*100:null;return <div className="result-card"><h3>Function graph</h3><svg viewBox="0 0 100 100" role="img" aria-label="Function curve across the selected x range" style={{width:"100%",height:"auto",minHeight:240,overflow:"visible"}}>{xAxis!==null&&<line x1="0" x2="100" y1={xAxis} y2={xAxis} stroke="currentColor" strokeOpacity=".3" vectorEffect="non-scaling-stroke"/>}{yAxis!==null&&<line y1="0" y2="100" x1={yAxis} x2={yAxis} stroke="currentColor" strokeOpacity=".3" vectorEffect="non-scaling-stroke"/>}<path d={path} fill="none" stroke="currentColor" strokeWidth="1.5" vectorEffect="non-scaling-stroke"/></svg><p className="muted">x: {displayNumber(xmin)} to {displayNumber(xmax)} · y: {displayNumber(ymin)} to {displayNumber(ymax)}</p></div>}
function FunctionPlotTool({definition}:{definition:typeof graphingCalculator}){const[expression,setExpression]=useState("x^2"),[minX,setMinX]=useState("-5"),[maxX,setMaxX]=useState("5");const input=useMemo(()=>({expression,minX:Number(minX),maxX:Number(maxX)}),[expression,minX,maxX]);const output=useMemo(()=>{try{return runCalculator(definition,input).output}catch{return null}},[definition,input]);const result:StructuredCalculationResult|null=output?{primaryResult:{id:"range",label:"Finite plotted points",value:output.points.length},metrics:[{id:"minimum",label:"Sampled minimum",value:displayNumber(output.minimum)},{id:"maximum",label:"Sampled maximum",value:displayNumber(output.maximum)}],series:[{id:"function",label:"y = f(x)",points:output.points}],methodology:"Every visible point is evaluated by CalcuMint's restricted deterministic expression engine; undefined samples are omitted."}:null;return <div className="calculator-ui"><label className="field"><span>f(x)</span><input value={expression} onChange={e=>setExpression(e.target.value)} inputMode="text"/></label><div className="field-grid"><NumberField label="Minimum x" value={minX} onChange={setMinX}/><NumberField label="Maximum x" value={maxX} onChange={setMaxX}/></div>{result?<><FinalResultPresentation result={result}/><FunctionCurve points={output!.points}/><Steps items={output!.steps}/></>:<Result value={null}/>}<CalculatorAccountActions calculatorSlug={definition.slug} calculatorVersion={1} input={input} output={output}/></div>}
function SeriesTool(){const[expression,setExpression]=useState("x^2"),[start,setStart]=useState("1"),[end,setEnd]=useState("10");const input=useMemo(()=>({expression,start:Number(start),end:Number(end)}),[expression,start,end]);const output=useMemo(()=>{try{return runCalculator(seriesCalculator,input).output}catch{return null}},[input]);const result:StructuredCalculationResult|null=output?{primaryResult:{id:"sum",label:"Finite series sum",value:displayNumber(output.sum)},metrics:[{id:"terms",label:"Number of terms",value:output.terms.length}],series:[{id:"partial-sums",label:"Partial sums",points:output.partialSums.map((y,i)=>({x:input.start+i,y}))}],methodology:"x is interpreted as the integer series index. Every term and partial sum is produced by the deterministic expression engine; no infinite-series convergence claim is made."}:null;return <div className="calculator-ui"><label className="field"><span>Term f(x)</span><input value={expression} onChange={e=>setExpression(e.target.value)} inputMode="text"/></label><div className="field-grid"><NumberField label="Start index" value={start} onChange={setStart}/><NumberField label="End index" value={end} onChange={setEnd}/></div>{result?<><FinalResultPresentation result={result}/><Steps items={output!.steps}/></>:<Result value={null}/>}<CalculatorAccountActions calculatorSlug={seriesCalculator.slug} calculatorVersion={1} input={input} output={output}/></div>}

function MatrixTool(){const init=["1","2","3","4","5","6","7","8"];const[v,setV]=useState(init),[operation,setOperation]=useState<"add"|"subtract"|"multiply">("multiply");const input=useMemo(()=>({a11:+v[0],a12:+v[1],a21:+v[2],a22:+v[3],b11:+v[4],b12:+v[5],b21:+v[6],b22:+v[7],operation}),[v,operation]);const output=useMemo(()=>{try{return runCalculator(matrixCalculator,input).output}catch{return null}},[input]);const result:StructuredCalculationResult|null=output?{primaryResult:{id:"matrix",label:"Result matrix",value:`[[${output.matrix[0][0]}, ${output.matrix[0][1]}], [${output.matrix[1][0]}, ${output.matrix[1][1]}]]`},metrics:[{id:"det",label:"Result determinant",value:displayNumber(output.determinant)},{id:"trace",label:"Result trace",value:displayNumber(output.trace)}],methodology:"Certified 2×2 matrix arithmetic. Addition/subtraction are element-wise; multiplication is row-by-column. Result properties are derived from the same matrix output."}:null;const field=(i:number,l:string)=><NumberField key={i} label={l} value={v[i]} onChange={x=>setV(a=>a.map((q,j)=>j===i?x:q))}/>;return <div className="calculator-ui"><h3>Matrix A</h3><div className="field-grid">{[0,1,2,3].map((i)=>field(i,`A${Math.floor(i/2)+1}${i%2+1}`))}</div><label className="field"><span>Operation</span><select value={operation} onChange={e=>setOperation(e.target.value as typeof operation)}><option value="add">A + B</option><option value="subtract">A − B</option><option value="multiply">A × B</option></select></label><h3>Matrix B</h3><div className="field-grid">{[4,5,6,7].map((i)=>field(i,`B${Math.floor((i-4)/2)+1}${(i-4)%2+1}`))}</div>{result?<><FinalResultPresentation result={result}/><Steps items={output!.steps}/></>:<Result value={null}/>}<CalculatorAccountActions calculatorSlug={matrixCalculator.slug} calculatorVersion={1} input={input} output={output}/></div>}
function SurfaceProjection({points}:{points:readonly{x:number;y:number;z:number}[]}){if(points.length<4)return null;const xs=points.map(p=>p.x),ys=points.map(p=>p.y),zs=points.map(p=>p.z),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),zmin=Math.min(...zs),zmax=Math.max(...zs),xr=xmax-xmin||1,yr=ymax-ymin||1,zr=zmax-zmin||1;const projected=points.map(p=>{const x=(p.x-xmin)/xr-.5,y=(p.y-ymin)/yr-.5,z=(p.z-zmin)/zr;return{sx:50+(x-y)*34,sy:66-(x+y)*17-z*30,z:p.z}});return <div className="result-card"><h3>3D surface projection</h3><svg viewBox="0 0 100 100" role="img" aria-label="Projected three-dimensional function surface" style={{width:"100%",height:"auto",minHeight:260}}>{projected.map((p,i)=><circle key={i} cx={p.sx} cy={p.sy} r=".7" fill="currentColor" opacity={.25+.7*(p.z-zmin)/zr}/>)}</svg><p className="muted">Projected from the full deterministic surface grid · z: {displayNumber(zmin)} to {displayNumber(zmax)}</p></div>}
function Surface3dTool(){const[expression,setExpression]=useState("x^2+y^2"),[minX,setMinX]=useState("-2"),[maxX,setMaxX]=useState("2"),[minY,setMinY]=useState("-2"),[maxY,setMaxY]=useState("2");const input=useMemo(()=>({expression,minX:+minX,maxX:+maxX,minY:+minY,maxY:+maxY}),[expression,minX,maxX,minY,maxY]);const output=useMemo(()=>{try{return runCalculator(functionPlotter3dCalculator,input).output}catch{return null}},[input]);const result:StructuredCalculationResult|null=output?{primaryResult:{id:"points",label:"Finite surface points",value:output.points.length},metrics:[{id:"min",label:"Sampled z minimum",value:displayNumber(output.minimum)},{id:"max",label:"Sampled z maximum",value:displayNumber(output.maximum)},{id:"grid",label:"Grid",value:`${output.gridSize}×${output.gridSize}`}],methodology:"A restricted deterministic expression engine evaluates the explicit surface on a finite rectangular grid. The projection consumes those same surface points."}:null;return <div className="calculator-ui"><label className="field"><span>z = f(x,y)</span><input value={expression} onChange={e=>setExpression(e.target.value)} inputMode="text"/></label><div className="field-grid"><NumberField label="Minimum x" value={minX} onChange={setMinX}/><NumberField label="Maximum x" value={maxX} onChange={setMaxX}/><NumberField label="Minimum y" value={minY} onChange={setMinY}/><NumberField label="Maximum y" value={maxY} onChange={setMaxY}/></div>{result?<><FinalResultPresentation result={result}/><SurfaceProjection points={output!.points}/><Steps items={output!.steps}/></>:<Result value={null}/>}<CalculatorAccountActions calculatorSlug={functionPlotter3dCalculator.slug} calculatorVersion={1} input={input} output={output}/></div>}

function TriangleTool({right=false}:{right?:boolean}){const[a,setA]=useState("3"),[b,setB]=useState("4"),[c,setC]=useState("5");const definition=right?rightTriangleCalculator:triangleCalculator;const input=useMemo(()=>right?{a:+a,b:+b}:{a:+a,b:+b,c:+c},[right,a,b,c]);const output=useMemo(()=>{try{return runCalculator(definition as typeof triangleCalculator,input as {a:number;b:number;c:number}).output}catch{return null}},[definition,input]);const result:StructuredCalculationResult|null=output?{primaryResult:{id:"area",label:"Area",value:displayNumber(output.area)},metrics:[{id:"perimeter",label:"Perimeter",value:displayNumber(output.perimeter)},{id:"A",label:"Angle A",value:displayNumber(output.angleA)+"°"},{id:"B",label:"Angle B",value:displayNumber(output.angleB)+"°"},{id:"C",label:"Angle C",value:displayNumber(output.angleC)+"°"}],methodology:right?"Pythagorean theorem and deterministic right-triangle identities.":"Heron's formula and the law of cosines from the same validated side lengths."}:null;return <div className="calculator-ui"><div className="field-grid"><NumberField label="Side a" value={a} onChange={setA}/><NumberField label="Side b" value={b} onChange={setB}/>{!right&&<NumberField label="Side c" value={c} onChange={setC}/>}</div>{result?<><FinalResultPresentation result={result}/><Steps items={output!.steps}/></>:<Result value={null}/>}<CalculatorAccountActions calculatorSlug={definition.slug} calculatorVersion={1} input={input} output={output}/></div>}
function PrismTool({volume=false}:{volume?:boolean}){const[l,setL]=useState("2"),[w,setW]=useState("3"),[h,setH]=useState("4"),definition=volume?volumeCalculator:surfaceAreaCalculator;const input=useMemo(()=>({length:+l,width:+w,height:+h}),[l,w,h]);const output=useMemo(()=>{try{return runCalculator(definition,input).output}catch{return null}},[definition,input]);const result:StructuredCalculationResult|null=output?{primaryResult:{id:volume?"volume":"surface",label:volume?"Volume":"Surface area",value:displayNumber(volume?output.volume:output.surfaceArea)},metrics:[{id:"surface",label:"Surface area",value:displayNumber(output.surfaceArea)},{id:"volume",label:"Volume",value:displayNumber(output.volume)}],methodology:"Deterministic rectangular-prism geometry using compatible input dimensions."}:null;return <div className="calculator-ui"><div className="field-grid"><NumberField label="Length" value={l} onChange={setL}/><NumberField label="Width" value={w} onChange={setW}/><NumberField label="Height" value={h} onChange={setH}/></div>{result?<><FinalResultPresentation result={result}/><Steps items={output!.steps}/></>:<Result value={null}/>}<CalculatorAccountActions calculatorSlug={definition.slug} calculatorVersion={1} input={input} output={output}/></div>}

function displayNumber(value:number){if(!Number.isFinite(value))return String(value);const normalized=Math.abs(value)<5e-13?0:Number(value.toPrecision(12));return normalized.toLocaleString(undefined,{maximumSignificantDigits:12});}
function PolynomialTool(){const[a,setA]=useState("1"),[b,setB]=useState("-6"),[c,setC]=useState("11"),[d,setD]=useState("-6");const input=useMemo(()=>({a:Number(a),b:Number(b),c:Number(c),d:Number(d)}),[a,b,c,d]);const output=useMemo(()=>{try{return runCalculator(polynomialCalculator,input).output}catch{return null}},[input]);const result:StructuredCalculationResult|null=output?{primaryResult:{id:"roots",label:"Distinct real root(s)",value:output.roots.map(displayNumber).join(", ")},metrics:[{id:"discriminant",label:"Cubic discriminant",value:output.discriminant}],series:[{id:"polynomial",label:"Polynomial around real roots",points:Array.from({length:21},(_,i)=>{const lo=Math.min(...output.roots)-2,hi=Math.max(...output.roots)+2,x=lo+(hi-lo)*i/20;return{x:Number(x.toPrecision(12)),y:Number((((input.a*x+input.b)*x+input.c)*x+input.d).toPrecision(12))}})}],methodology:"The certified cubic engine normalizes the polynomial and uses deterministic Cardano or trigonometric identities according to its discriminant."}:null;return <div className="calculator-ui"><div className="field-grid">{[["a (x³)",a,setA],["b (x²)",b,setB],["c (x)",c,setC],["d",d,setD]].map(([l,v,f])=><NumberField key={l as string} label={l as string} value={v as string} onChange={f as (v:string)=>void}/>)}</div>{result?<><FinalResultPresentation result={result}/><Steps items={output!.steps}/></>:<Result value={null}/>}<CalculatorAccountActions calculatorSlug={polynomialCalculator.slug} calculatorVersion={1} input={input} output={output}/></div>}
function RootFinderTool(){const[a,setA]=useState("0"),[b,setB]=useState("1"),[c,setC]=useState("0"),[d,setD]=useState("-2"),[left,setLeft]=useState("1"),[right,setRight]=useState("2");const input=useMemo(()=>({a:Number(a),b:Number(b),c:Number(c),d:Number(d),left:Number(left),right:Number(right)}),[a,b,c,d,left,right]);const output=useMemo(()=>{try{return runCalculator(rootFinderCalculator,input).output}catch{return null}},[input]);const result:StructuredCalculationResult|null=output?{primaryResult:{id:"root",label:"Root",value:output.root},metrics:[{id:"residual",label:"Residual",value:output.residual},{id:"iterations",label:"Iterations",value:output.iterations},{id:"bracket",label:"Final bracket",value:`[${displayNumber(output.bracket[0])}, ${displayNumber(output.bracket[1])}]`}],methodology:"The certified numerical engine applies bounded bisection only to a validated sign-changing interval."}:null;return <div className="calculator-ui"><div className="field-grid">{[["a (x³)",a,setA],["b (x²)",b,setB],["c (x)",c,setC],["d",d,setD],["Left bound",left,setLeft],["Right bound",right,setRight]].map(([l,v,f])=><NumberField key={l as string} label={l as string} value={v as string} onChange={f as (v:string)=>void}/>)}</div>{result?<><FinalResultPresentation result={result}/><Steps items={output!.steps}/></>:<Result value={null}/>}<CalculatorAccountActions calculatorSlug={rootFinderCalculator.slug} calculatorVersion={1} input={input} output={output}/></div>}

function Result({value,displayValue}:{value:number|null;displayValue?:string}){return <div className="result-box" aria-live="polite"><span>Result</span><strong>{value===null||!Number.isFinite(value)?"Enter valid inputs":displayValue??value.toLocaleString(undefined,{maximumFractionDigits:12})}</strong></div>}
function LaunchTool({slug}:{slug:string}){const spec=getLaunchSpec(slug)!;const definition=useMemo(()=>launchDefinition(spec),[spec]);const[values,setValues]=useState<Record<string,string>>(()=>Object.fromEntries(spec.fields.map(x=>[x.key,String(x.defaultValue)])));const input=useMemo(()=>Object.fromEntries(spec.fields.map(x=>[x.key,Number(values[x.key])])),[spec,values]);const result=useMemo(()=>{try{const n=runCalculator(definition,input).output.result;return Number.isFinite(n)?n:null}catch{return null}},[definition,input]);const displayValue=result!==null&&spec.formatResult?spec.formatResult(input,result):undefined;return <div className="calculator-ui"><div className="field-grid">{spec.fields.map(field=><NumberField key={field.key} label={field.label} min={field.min} value={values[field.key]??""} onChange={value=>setValues(current=>({...current,[field.key]:value}))}/>)}</div><Result value={result} displayValue={displayValue}/><CalculatorAccountActions calculatorSlug={slug} calculatorVersion={1} input={input} output={result===null?null:{result}}/>{result!==null&&<AiResultExplanation calculatorName={spec.title} formula={spec.formula} assumptions={["The displayed deterministic formula is the source of the numeric result."]} values={input} result={{result}}/>}</div>}
export function CalculatorInteractive({slug}:{slug:string}){if(slug===triangleCalculator.slug)return <TriangleTool/>;if(slug===rightTriangleCalculator.slug)return <TriangleTool right/>;if(slug===surfaceAreaCalculator.slug)return <PrismTool/>;if(slug===volumeCalculator.slug)return <PrismTool volume/>;if(slug===matrixCalculator.slug)return <MatrixTool/>;if(slug===functionPlotter3dCalculator.slug)return <Surface3dTool/>;if(slug===graphingCalculator.slug)return <FunctionPlotTool definition={graphingCalculator}/>;if(slug===functionPlotter2dCalculator.slug)return <FunctionPlotTool definition={functionPlotter2dCalculator}/>;if(slug===seriesCalculator.slug)return <SeriesTool/>;if(slug===derivativeCalculator.slug)return <DerivativeTool/>;if(slug===integralCalculator.slug)return <IntegralTool/>;if(slug===limitCalculator.slug)return <LimitTool/>;if(slug===equationSolverCalculator.slug)return <EquationSolverTool/>;if(slug===polynomialCalculator.slug)return <PolynomialTool/>;if(slug===rootFinderCalculator.slug)return <RootFinderTool/>;if(slug===rrefCalculator.slug)return <RrefTool/>;if(slug===vectorCalculator.slug)return <VectorTool/>;if(slug===sequenceCalculator.slug)return <SequenceTool/>;if(slug===systemOfEquationsCalculator.slug)return <SystemEquationsTool/>;if(slug===matrixInverseCalculator.slug)return <MatrixInverseTool/>;if(slug===complexNumberCalculator.slug)return <ComplexNumberTool/>;if(slug===linearEquationCalculator.slug)return <LinearEquationTool/>;if(slug===quadraticFormulaCalculator.slug)return <QuadraticFormulaTool/>;if(slug===matrixDeterminantCalculator.slug)return <MatrixDeterminantTool/>;if(slug===loanAnalysisCalculator.slug)return <LoanPaymentReferenceTool calculatorSlug={loanAnalysisCalculator.slug}/>;if(slug===loanPaymentCalculator.slug)return <LoanPaymentReferenceTool calculatorSlug={loanPaymentCalculator.slug}/>;if(slug==="mortgage-payment")return <MortgageReferenceTool/>;if(slug===bmiCalculator.slug)return <BmiReferenceTool/>;if(slug===breakEvenCalculator.slug)return <BreakEvenReferenceTool/>;if(slug===percentageCalculator.slug)return <PercentageTool/>;if(slug===unitConversionCalculator.slug)return <UnitTool/>;if(slug===simpleInterestCalculator.slug)return <SimpleInterestTool/>;if(slug===savingsGoalCalculator.slug)return <SavingsGoalTool/>;if(slug===emergencyFundCalculator.slug)return <EmergencyFundTool/>;if(slug===roiCalculator.slug)return <RoiTool/>;if(slug===inflationCalculator.slug)return <InflationTool/>;if(slug===rateConversionCalculator.slug)return <RateConversionTool/>;if(slug===netWorthCalculator.slug)return <NetWorthTool/>;if(slug===termDepositCalculator.slug)return <TermDepositTool/>;if(slug===recurringDepositCalculator.slug)return <RecurringDepositTool/>;if(slug===sipCalculator.slug)return <SipTool/>;if(slug===stepUpSipCalculator.slug)return <StepUpSipTool/>;if(slug===swpCalculator.slug)return <SwpTool/>;if(slug===creditCardPayoffCalculator.slug)return <CreditCardTool/>;if(slug===loanAffordabilityCalculator.slug)return <AffordabilityTool/>;if(slug===loanRefinanceCalculator.slug)return <RefinanceTool/>;if(slug===loanPrepaymentCalculator.slug)return <PrepaymentTool/>;if(slug===loanComparisonCalculator.slug)return <LoanComparisonTool/>;if(slug===investmentMathCalculator.slug)return <InvestmentGrowthTool/>;if(slug===debtPayoffCalculator.slug)return <DebtPayoffTool/>;if(slug===compoundInterestCalculator.slug)return <CompoundInterestTool/>;if(getLaunchSpec(slug))return <LaunchTool slug={slug}/>;return <p className="muted">This calculator does not yet have a public interface.</p>}
